/*
 * atg_kc705_mig: The KC705 memory: MIG 7 Series DDR3 (1 GB, 64 bit, AXI4
 * 512 bit, ui_clk 200 MHz, regenerated by TCL, design §4.1) behind two
 * AXI4 slaves: s_* in gclk (atg_top's m_*) and s2_* in s2_clk (the PCIe
 * BAR2 window, 128 bit; ws288 p013: the host's window does not go through
 * the MC, so the aperture, quiesce and the CP's RESET do not touch it).
 * An AXI Interconnect joins them in front of the MIG (clock and width
 * conversion, arbitration).  See spec/boards/kc705/lib/atg_kc705_mig.md.
 *
 * Two IP cores, generated by boards/kc705/ip.tcl (not committed) under
 * these module names:
 *
 *   atg_kc705_axi_ic   AXI Interconnect: 2 slave ports (S00: 512 bit,
 *                      ID 4, gclk; S01: 128 bit, ID 4, s2_clk), 1 master
 *                      (M00: 512 bit, ID 4 + the port, ui_clk), all
 *                      clocks asynchronous.
 *   atg_kc705_ddr3     MIG 7 Series, the board file's DDR3 preset (64 bit,
 *                      800 MHz, 4:1, ui_clk 200 MHz) with the AXI4
 *                      interface (data 512, address 30, ID 5), system
 *                      clock "No Buffer" (ref_clk from atg_kc705_clk), the
 *                      reference clock "Use System Clock", sys_rst active
 *                      low, XADC on (device_temp).
 *
 * The MIG's AXI reset (aresetn) is ui_clk_sync_rst inverted and registered
 * in ui_clk; the interconnect's master side uses it too.  mem_ready is
 * init_calib_complete in gclk through am_sync.  The MIG takes address
 * bits 29:0: atg_top's LOCAL_BASE + offset and BAR2's offset are the same
 * DDR3 byte.  The port names of both cores are those the TCL's generated
 * cores have (checked with Vivado 2026.1, ws288 p013).  In simulation this
 * whole module is replaced by sim/models/kc705/atg_kc705_mig.v.
 */

`timescale 1ns / 1ps
`default_nettype none

module atg_kc705_mig (
	input wire clk,
	input wire rst_n,
	input wire sys_clk,
	input wire sys_rst_n,
	output wire mem_ready,
	/* AXI4 slave (gclk), atg_top's m_* */
	input wire [31:0] s_awaddr,
	input wire [7:0] s_awlen,
	input wire [2:0] s_awsize,
	input wire [1:0] s_awburst,
	input wire [3:0] s_awcache,
	input wire [2:0] s_awprot,
	input wire s_awvalid,
	output wire s_awready,
	input wire [511:0] s_wdata,
	input wire [63:0] s_wstrb,
	input wire s_wlast,
	input wire s_wvalid,
	output wire s_wready,
	output wire [1:0] s_bresp,
	output wire s_bvalid,
	input wire s_bready,
	input wire [31:0] s_araddr,
	input wire [7:0] s_arlen,
	input wire [2:0] s_arsize,
	input wire [1:0] s_arburst,
	input wire [3:0] s_arcache,
	input wire [2:0] s_arprot,
	input wire s_arvalid,
	output wire s_arready,
	output wire [511:0] s_rdata,
	output wire [1:0] s_rresp,
	output wire s_rlast,
	output wire s_rvalid,
	input wire s_rready,
	/* AXI4 slave (s2_clk), the PCIe BAR2 window: 128-bit, the DDR3 offset */
	input wire s2_clk,
	input wire s2_rst_n,
	input wire [25:0] s2_awaddr,
	input wire [3:0] s2_awid,
	input wire [7:0] s2_awlen,
	input wire [2:0] s2_awsize,
	input wire [1:0] s2_awburst,
	input wire s2_awvalid,
	output wire s2_awready,
	input wire [127:0] s2_wdata,
	input wire [15:0] s2_wstrb,
	input wire s2_wlast,
	input wire s2_wvalid,
	output wire s2_wready,
	output wire [3:0] s2_bid,
	output wire [1:0] s2_bresp,
	output wire s2_bvalid,
	input wire s2_bready,
	input wire [25:0] s2_araddr,
	input wire [3:0] s2_arid,
	input wire [7:0] s2_arlen,
	input wire [2:0] s2_arsize,
	input wire [1:0] s2_arburst,
	input wire s2_arvalid,
	output wire s2_arready,
	output wire [127:0] s2_rdata,
	output wire [3:0] s2_rid,
	output wire [1:0] s2_rresp,
	output wire s2_rlast,
	output wire s2_rvalid,
	input wire s2_rready,
	/* DDR3 pins */
	inout wire [63:0] ddr3_dq,
	inout wire [7:0] ddr3_dqs_p,
	inout wire [7:0] ddr3_dqs_n,
	output wire [13:0] ddr3_addr,
	output wire [2:0] ddr3_ba,
	output wire ddr3_ras_n,
	output wire ddr3_cas_n,
	output wire ddr3_we_n,
	output wire ddr3_reset_n,
	output wire ddr3_ck_p,
	output wire ddr3_ck_n,
	output wire ddr3_cke,
	output wire ddr3_cs_n,
	output wire [7:0] ddr3_dm,
	output wire ddr3_odt
);
	wire ui_clk, ui_rst, calib;
	reg aresetn = 1'b0;

	always @(posedge ui_clk)
		aresetn <= !ui_rst;

	am_sync sync_ready (.clk(clk), .rst_n(rst_n), .d(calib), .q(mem_ready));

	/* ---- BAR2: s2_clk -> gclk (128 bit), 128 -> 512 bit ---- */
	wire [3:0] c_awid, c_bid, c_arid, c_rid;
	wire [31:0] c_awaddr, c_araddr, e_awaddr, e_araddr;
	wire [7:0] c_awlen, c_arlen, e_awlen, e_arlen;
	wire [2:0] c_awsize, c_arsize, c_awprot, c_arprot, e_awsize, e_arsize, e_awprot, e_arprot;
	wire [1:0] c_awburst, c_arburst, c_bresp, c_rresp, e_awburst, e_arburst, e_bresp, e_rresp;
	wire [3:0] c_awcache, c_arcache, c_awregion, c_arregion, c_awqos, c_arqos;
	wire [3:0] e_awcache, e_arcache, e_awregion, e_arregion, e_awqos, e_arqos;
	wire c_awlock, c_arlock, e_awlock, e_arlock;
	wire c_awvalid, c_awready, c_wlast, c_wvalid, c_wready, c_bvalid, c_bready;
	wire c_arvalid, c_arready, c_rlast, c_rvalid, c_rready;
	wire e_awvalid, e_awready, e_wlast, e_wvalid, e_wready, e_bvalid, e_bready;
	wire e_arvalid, e_arready, e_rlast, e_rvalid, e_rready;
	wire [127:0] c_wdata, c_rdata;
	wire [15:0] c_wstrb;
	wire [511:0] e_wdata, e_rdata;
	wire [63:0] e_wstrb;

	atg_kc705_bar2_cc bar2_cc (
		.s_axi_aclk(s2_clk), .s_axi_aresetn(s2_rst_n),
		.s_axi_awid(s2_awid), .s_axi_awaddr({6'd0, s2_awaddr}), .s_axi_awlen(s2_awlen),
		.s_axi_awsize(s2_awsize), .s_axi_awburst(s2_awburst), .s_axi_awlock(1'b0),
		.s_axi_awcache(4'd0), .s_axi_awprot(3'd0), .s_axi_awregion(4'd0), .s_axi_awqos(4'd0),
		.s_axi_awvalid(s2_awvalid), .s_axi_awready(s2_awready), .s_axi_wdata(s2_wdata),
		.s_axi_wstrb(s2_wstrb), .s_axi_wlast(s2_wlast), .s_axi_wvalid(s2_wvalid),
		.s_axi_wready(s2_wready), .s_axi_bid(s2_bid), .s_axi_bresp(s2_bresp),
		.s_axi_bvalid(s2_bvalid), .s_axi_bready(s2_bready), .s_axi_arid(s2_arid),
		.s_axi_araddr({6'd0, s2_araddr}), .s_axi_arlen(s2_arlen), .s_axi_arsize(s2_arsize),
		.s_axi_arburst(s2_arburst), .s_axi_arlock(1'b0), .s_axi_arcache(4'd0),
		.s_axi_arprot(3'd0), .s_axi_arregion(4'd0), .s_axi_arqos(4'd0),
		.s_axi_arvalid(s2_arvalid), .s_axi_arready(s2_arready), .s_axi_rid(s2_rid),
		.s_axi_rdata(s2_rdata), .s_axi_rresp(s2_rresp), .s_axi_rlast(s2_rlast),
		.s_axi_rvalid(s2_rvalid), .s_axi_rready(s2_rready),
		.m_axi_aclk(clk), .m_axi_aresetn(rst_n),
		.m_axi_awid(c_awid), .m_axi_awaddr(c_awaddr), .m_axi_awlen(c_awlen),
		.m_axi_awsize(c_awsize), .m_axi_awburst(c_awburst), .m_axi_awlock(c_awlock),
		.m_axi_awcache(c_awcache), .m_axi_awprot(c_awprot), .m_axi_awregion(c_awregion),
		.m_axi_awqos(c_awqos), .m_axi_awvalid(c_awvalid), .m_axi_awready(c_awready),
		.m_axi_wdata(c_wdata), .m_axi_wstrb(c_wstrb), .m_axi_wlast(c_wlast),
		.m_axi_wvalid(c_wvalid), .m_axi_wready(c_wready), .m_axi_bid(c_bid),
		.m_axi_bresp(c_bresp), .m_axi_bvalid(c_bvalid), .m_axi_bready(c_bready),
		.m_axi_arid(c_arid), .m_axi_araddr(c_araddr), .m_axi_arlen(c_arlen),
		.m_axi_arsize(c_arsize), .m_axi_arburst(c_arburst), .m_axi_arlock(c_arlock),
		.m_axi_arcache(c_arcache), .m_axi_arprot(c_arprot), .m_axi_arregion(c_arregion),
		.m_axi_arqos(c_arqos), .m_axi_arvalid(c_arvalid), .m_axi_arready(c_arready),
		.m_axi_rid(c_rid), .m_axi_rdata(c_rdata), .m_axi_rresp(c_rresp),
		.m_axi_rlast(c_rlast), .m_axi_rvalid(c_rvalid), .m_axi_rready(c_rready)
	);

	atg_kc705_bar2_up bar2_up (
		.s_axi_aclk(clk), .s_axi_aresetn(rst_n),
		.s_axi_awid(c_awid), .s_axi_awaddr(c_awaddr), .s_axi_awlen(c_awlen),
		.s_axi_awsize(c_awsize), .s_axi_awburst(c_awburst), .s_axi_awlock(c_awlock),
		.s_axi_awcache(c_awcache), .s_axi_awprot(c_awprot), .s_axi_awregion(c_awregion),
		.s_axi_awqos(c_awqos), .s_axi_awvalid(c_awvalid), .s_axi_awready(c_awready),
		.s_axi_wdata(c_wdata), .s_axi_wstrb(c_wstrb), .s_axi_wlast(c_wlast),
		.s_axi_wvalid(c_wvalid), .s_axi_wready(c_wready), .s_axi_bid(c_bid),
		.s_axi_bresp(c_bresp), .s_axi_bvalid(c_bvalid), .s_axi_bready(c_bready),
		.s_axi_arid(c_arid), .s_axi_araddr(c_araddr), .s_axi_arlen(c_arlen),
		.s_axi_arsize(c_arsize), .s_axi_arburst(c_arburst), .s_axi_arlock(c_arlock),
		.s_axi_arcache(c_arcache), .s_axi_arprot(c_arprot), .s_axi_arregion(c_arregion),
		.s_axi_arqos(c_arqos), .s_axi_arvalid(c_arvalid), .s_axi_arready(c_arready),
		.s_axi_rid(c_rid), .s_axi_rdata(c_rdata), .s_axi_rresp(c_rresp),
		.s_axi_rlast(c_rlast), .s_axi_rvalid(c_rvalid), .s_axi_rready(c_rready),
		.m_axi_awaddr(e_awaddr), .m_axi_awlen(e_awlen), .m_axi_awsize(e_awsize),
		.m_axi_awburst(e_awburst), .m_axi_awlock(e_awlock), .m_axi_awcache(e_awcache),
		.m_axi_awprot(e_awprot), .m_axi_awregion(e_awregion), .m_axi_awqos(e_awqos),
		.m_axi_awvalid(e_awvalid), .m_axi_awready(e_awready), .m_axi_wdata(e_wdata),
		.m_axi_wstrb(e_wstrb), .m_axi_wlast(e_wlast), .m_axi_wvalid(e_wvalid),
		.m_axi_wready(e_wready), .m_axi_bresp(e_bresp), .m_axi_bvalid(e_bvalid),
		.m_axi_bready(e_bready), .m_axi_araddr(e_araddr), .m_axi_arlen(e_arlen),
		.m_axi_arsize(e_arsize), .m_axi_arburst(e_arburst), .m_axi_arlock(e_arlock),
		.m_axi_arcache(e_arcache), .m_axi_arprot(e_arprot), .m_axi_arregion(e_arregion),
		.m_axi_arqos(e_arqos), .m_axi_arvalid(e_arvalid), .m_axi_arready(e_arready),
		.m_axi_rdata(e_rdata), .m_axi_rresp(e_rresp), .m_axi_rlast(e_rlast),
		.m_axi_rvalid(e_rvalid), .m_axi_rready(e_rready)
	);

	/* ---- The GPU (S00) and BAR2 (S01) to one master, gclk ---- */
	wire [0:0] g_awid, g_bid, g_arid, g_rid;
	wire [31:0] g_awaddr, g_araddr;
	wire [7:0] g_awlen, g_arlen;
	wire [2:0] g_awsize, g_arsize, g_awprot, g_arprot;
	wire [1:0] g_awburst, g_arburst, g_bresp, g_rresp;
	wire [3:0] g_awcache, g_arcache, g_awregion, g_arregion, g_awqos, g_arqos;
	wire g_awlock, g_arlock, g_awvalid, g_awready, g_wlast, g_wvalid, g_wready, g_bvalid;
	wire g_bready, g_arvalid, g_arready, g_rlast, g_rvalid, g_rready;
	wire [511:0] g_wdata, g_rdata;
	wire [63:0] g_wstrb;
	wire [1:0] x_bid, x_rid;
	wire [1023:0] x_rdata;
	wire [3:0] x_bresp, x_rresp;
	wire [1:0] x_awready, x_wready, x_bvalid, x_arready, x_rlast, x_rvalid;

	atg_kc705_mem_xbar xbar (
		.aclk(clk), .aresetn(rst_n),
		.s_axi_awid(2'b00), .s_axi_awaddr({e_awaddr, s_awaddr}), .s_axi_awlen({e_awlen, s_awlen}),
		.s_axi_awsize({e_awsize, s_awsize}), .s_axi_awburst({e_awburst, s_awburst}),
		.s_axi_awlock({e_awlock, 1'b0}), .s_axi_awcache({e_awcache, s_awcache}),
		.s_axi_awprot({e_awprot, s_awprot}), .s_axi_awqos({e_awqos, 4'd0}),
		.s_axi_awvalid({e_awvalid, s_awvalid}), .s_axi_awready(x_awready),
		.s_axi_wdata({e_wdata, s_wdata}), .s_axi_wstrb({e_wstrb, s_wstrb}),
		.s_axi_wlast({e_wlast, s_wlast}), .s_axi_wvalid({e_wvalid, s_wvalid}),
		.s_axi_wready(x_wready), .s_axi_bid(x_bid), .s_axi_bresp(x_bresp),
		.s_axi_bvalid(x_bvalid), .s_axi_bready({e_bready, s_bready}),
		.s_axi_arid(2'b00), .s_axi_araddr({e_araddr, s_araddr}),
		.s_axi_arlen({e_arlen, s_arlen}), .s_axi_arsize({e_arsize, s_arsize}),
		.s_axi_arburst({e_arburst, s_arburst}), .s_axi_arlock({e_arlock, 1'b0}),
		.s_axi_arcache({e_arcache, s_arcache}), .s_axi_arprot({e_arprot, s_arprot}),
		.s_axi_arqos({e_arqos, 4'd0}), .s_axi_arvalid({e_arvalid, s_arvalid}),
		.s_axi_arready(x_arready), .s_axi_rid(x_rid), .s_axi_rdata(x_rdata),
		.s_axi_rresp(x_rresp), .s_axi_rlast(x_rlast), .s_axi_rvalid(x_rvalid),
		.s_axi_rready({e_rready, s_rready}),
		.m_axi_awid(g_awid), .m_axi_awaddr(g_awaddr), .m_axi_awlen(g_awlen),
		.m_axi_awsize(g_awsize), .m_axi_awburst(g_awburst), .m_axi_awlock(g_awlock),
		.m_axi_awcache(g_awcache), .m_axi_awprot(g_awprot), .m_axi_awregion(g_awregion),
		.m_axi_awqos(g_awqos), .m_axi_awvalid(g_awvalid), .m_axi_awready(g_awready),
		.m_axi_wdata(g_wdata), .m_axi_wstrb(g_wstrb), .m_axi_wlast(g_wlast),
		.m_axi_wvalid(g_wvalid), .m_axi_wready(g_wready), .m_axi_bid(g_bid),
		.m_axi_bresp(g_bresp), .m_axi_bvalid(g_bvalid), .m_axi_bready(g_bready),
		.m_axi_arid(g_arid), .m_axi_araddr(g_araddr), .m_axi_arlen(g_arlen),
		.m_axi_arsize(g_arsize), .m_axi_arburst(g_arburst), .m_axi_arlock(g_arlock),
		.m_axi_arcache(g_arcache), .m_axi_arprot(g_arprot), .m_axi_arregion(g_arregion),
		.m_axi_arqos(g_arqos), .m_axi_arvalid(g_arvalid), .m_axi_arready(g_arready),
		.m_axi_rid(g_rid), .m_axi_rdata(g_rdata), .m_axi_rresp(g_rresp),
		.m_axi_rlast(g_rlast), .m_axi_rvalid(g_rvalid), .m_axi_rready(g_rready)
	);
	assign s_awready = x_awready[0];
	assign s_wready = x_wready[0];
	assign s_bresp = x_bresp[1:0];
	assign s_bvalid = x_bvalid[0];
	assign s_arready = x_arready[0];
	assign s_rdata = x_rdata[511:0];
	assign s_rresp = x_rresp[1:0];
	assign s_rlast = x_rlast[0];
	assign s_rvalid = x_rvalid[0];
	assign e_awready = x_awready[1];
	assign e_wready = x_wready[1];
	assign e_bresp = x_bresp[3:2];
	assign e_bvalid = x_bvalid[1];
	assign e_arready = x_arready[1];
	assign e_rdata = x_rdata[1023:512];
	assign e_rresp = x_rresp[3:2];
	assign e_rlast = x_rlast[1];
	assign e_rvalid = x_rvalid[1];

	/* ---- gclk -> ui_clk, the MIG ---- */
	wire [0:0] u_awid, u_bid, u_arid, u_rid;
	wire [31:0] u_awaddr, u_araddr;
	wire [7:0] u_awlen, u_arlen;
	wire [2:0] u_awsize, u_arsize, u_awprot, u_arprot;
	wire [1:0] u_awburst, u_arburst, u_bresp, u_rresp;
	wire [3:0] u_awcache, u_arcache, u_awqos, u_arqos, u_bid4, u_rid4;
	wire [0:0] u_awlock, u_arlock;
	wire u_awvalid, u_awready, u_wlast, u_wvalid, u_wready, u_bvalid, u_bready;
	wire u_arvalid, u_arready, u_rlast, u_rvalid, u_rready;
	wire [511:0] u_wdata, u_rdata;
	wire [63:0] u_wstrb;

	atg_kc705_axi_cc cc (
		.s_axi_aclk(clk), .s_axi_aresetn(rst_n),
		.s_axi_awid(g_awid), .s_axi_awaddr(g_awaddr), .s_axi_awlen(g_awlen),
		.s_axi_awsize(g_awsize), .s_axi_awburst(g_awburst), .s_axi_awlock(g_awlock),
		.s_axi_awcache(g_awcache), .s_axi_awprot(g_awprot), .s_axi_awregion(g_awregion),
		.s_axi_awqos(g_awqos), .s_axi_awvalid(g_awvalid), .s_axi_awready(g_awready),
		.s_axi_wdata(g_wdata), .s_axi_wstrb(g_wstrb), .s_axi_wlast(g_wlast),
		.s_axi_wvalid(g_wvalid), .s_axi_wready(g_wready), .s_axi_bid(g_bid),
		.s_axi_bresp(g_bresp), .s_axi_bvalid(g_bvalid), .s_axi_bready(g_bready),
		.s_axi_arid(g_arid), .s_axi_araddr(g_araddr), .s_axi_arlen(g_arlen),
		.s_axi_arsize(g_arsize), .s_axi_arburst(g_arburst), .s_axi_arlock(g_arlock),
		.s_axi_arcache(g_arcache), .s_axi_arprot(g_arprot), .s_axi_arregion(g_arregion),
		.s_axi_arqos(g_arqos), .s_axi_arvalid(g_arvalid), .s_axi_arready(g_arready),
		.s_axi_rid(g_rid), .s_axi_rdata(g_rdata), .s_axi_rresp(g_rresp),
		.s_axi_rlast(g_rlast), .s_axi_rvalid(g_rvalid), .s_axi_rready(g_rready),
		.m_axi_aclk(ui_clk), .m_axi_aresetn(aresetn),
		.m_axi_awid(u_awid), .m_axi_awaddr(u_awaddr), .m_axi_awlen(u_awlen),
		.m_axi_awsize(u_awsize), .m_axi_awburst(u_awburst), .m_axi_awlock(u_awlock),
		.m_axi_awcache(u_awcache), .m_axi_awprot(u_awprot), .m_axi_awregion(),
		.m_axi_awqos(u_awqos), .m_axi_awvalid(u_awvalid), .m_axi_awready(u_awready),
		.m_axi_wdata(u_wdata), .m_axi_wstrb(u_wstrb), .m_axi_wlast(u_wlast),
